 "_t14/config.mjs": "// Server-side configuration: read once at start-up, fail fast if something is missing.\nconst required = ['DATABASE_URL', 'PAYMENT_SECRET'];\n\nconst missing = required.filter((name) => !process.env[name]);\nif (missing.length > 0) {\n  console.error('Missing environment variables: ' + missing.join(', '));\n  console.error('Copy .env.example to .env and fill them in.');\n  process.exit(1);\n}\n\nexport const config = {\n  databaseUrl: process.env.DATABASE_URL,\n  paymentSecret: process.env.PAYMENT_SECRET,\n  port: Number(process.env.PORT ?? 3000),\n};\n\n// Never print secrets — print that they exist\nconsole.log('config ok · port', config.port, '· database', new URL(config.databaseUrl).host, '· payment secret', config.paymentSecret ? 'set (' + config.paymentSecret.length + ' chars)' : 'missing');\n",
 "_t14/count.mjs": "// Loads a URL in Chromium and counts what the browser downloaded.\nimport { chromium } from 'playwright';\nconst [url, label] = process.argv.slice(2);\nconst browser = await chromium.launch();\nconst page = await browser.newPage();\nlet n = 0, bytes = 0;\npage.on('response', async (r) => { n++; try { bytes += (await r.body()).length; } catch {} });\nawait page.goto(url, { waitUntil: 'networkidle' });\nconsole.log(label.padEnd(30), n, 'requests,', (bytes / 1024).toFixed(1), 'KB downloaded');\nawait browser.close();\n",
